import sys

def solve():
    # Read all input from standard input
    # split() handles newlines and spaces automatically
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)
    try:
        H = int(next(iterator))
        W = int(next(iterator))
        D = int(next(iterator))

        S = []
        for _ in range(H):
            S.append(next(iterator))
    except StopIteration:
        return

    # Identify all floor cells
    floors = []
    for r in range(H):
        for c in range(W):
            if S[r][c] == '.':
                floors.append((r, c))

    max_humidified = 0
    n = len(floors)

    # Iterate over all pairs of distinct floor cells to place humidifiers
    # Since there are at least two floor cells, n >= 2
    for i in range(n):
        for j in range(i + 1, n):
            r1, c1 = floors[i]
            r2, c2 = floors[j]

            current_humidified = 0
            # Check all floor cells to see if they are humidified by either humidifier
            for (r, c) in floors:
                dist1 = abs(r - r1) + abs(c - c1)
                dist2 = abs(r - r2) + abs(c - c2)

                if dist1 <= D or dist2 <= D:
                    current_humidified += 1

            if current_humidified > max_humidified:
                max_humidified = current_humidified

    print(max_humidified)

if __name__ == '__main__':
    solve()
